const TOKEN_PRICE=0.025;
function calcRewards(){const stake=+document.getElementById('calcStake').value||0;const apr=+document.getElementById('calcTier').value/100;const yearly=stake*apr;const monthly=yearly/12;const daily=yearly/365;document.getElementById('calcDaily').textContent=daily.toLocaleString(undefined,{maximumFractionDigits:0})+' VRDX';document.getElementById('calcMonthly').textContent=monthly.toLocaleString(undefined,{maximumFractionDigits:0})+' VRDX';document.getElementById('calcYearly').textContent=yearly.toLocaleString(undefined,{maximumFractionDigits:0})+' VRDX';document.getElementById('calcDailyUSD').textContent='$'+(daily*TOKEN_PRICE).toLocaleString(undefined,{maximumFractionDigits:2});document.getElementById('calcMonthlyUSD').textContent='$'+(monthly*TOKEN_PRICE).toLocaleString(undefined,{maximumFractionDigits:2});document.getElementById('calcYearlyUSD').textContent='$'+(yearly*TOKEN_PRICE).toLocaleString(undefined,{maximumFractionDigits:2})}
calcRewards();

async function loadPageMetrics() {
    try {
        const res = await fetch('/rpc', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'chain_getHeader', params: [], id: 1})
        });
        const data = await res.json();
        const height = parseInt(data.result?.number || '0x0', 16);
        document.querySelectorAll('[data-block-height]').forEach(el => {
            el.textContent = '#' + height.toLocaleString();
        });
    } catch(e) {}
}
loadPageMetrics();
setInterval(loadPageMetrics, 15000);

// Live RPC data for incentives page
async function rpc(method, params = []) {
    const res = await fetch('/rpc', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({jsonrpc: '2.0', method, params, id: Math.random()})
    });
    const data = await res.json();
    return data.result;
}

async function loadIncentiveStats() {
    try {
        // Get active validators count
        const activeVals = await rpc('dpos_activeValidators', []);
        const count = activeVals ? activeVals.length : 14;
        document.querySelectorAll('#stat-vals, #stat-vals2').forEach(el => el.textContent = count);

        // Get all validators and their stakes
        const allVals = await rpc('dpos_allValidators', []);
        if (allVals && Array.isArray(allVals)) {
            let totalStaked = 0;
            for (const addr of allVals) {
                try {
                    const stake = await rpc('dpos_validatorStake', [addr]);
                    totalStaked += parseInt(stake) || 0;
                } catch(e) {}
            }
            // Convert from Planck (12 decimals) to VRDX
            const vrdxStaked = totalStaked / 1e12;
            const stakedStr = vrdxStaked >= 1e9 ? (vrdxStaked / 1e9).toFixed(1) + 'B' :
                              vrdxStaked >= 1e6 ? (vrdxStaked / 1e6).toFixed(1) + 'M' :
                              vrdxStaked >= 1e3 ? (vrdxStaked / 1e3).toFixed(1) + 'K' : vrdxStaked.toFixed(0);
            document.querySelectorAll('#stat-staked, #stat-staked2').forEach(el => el.textContent = stakedStr);
        }

        // Get block height
        const header = await rpc('chain_getHeader', []);
        const blockNum = parseInt(header?.number || '0x0', 16);
        const blockEl = document.getElementById('stat-block');
        if (blockEl) blockEl.textContent = '#' + blockNum;

        // Get peers
        const health = await rpc('system_health', []);
        const peersEl = document.getElementById('stat-peers');
        if (peersEl) peersEl.textContent = health?.peers || 8;
    } catch(e) {
        }
}
loadIncentiveStats();
setInterval(loadIncentiveStats, 15000);
